 WHEN NEW.daemon_ledger_sequence<=coalesce((SELECT max(daemon_ledger_sequence) FROM amendment_registrations),-1) THEN RAISE(ABORT,'amendment ledger order is not append-only')
 WHEN NEW.registration_ordinal!=coalesce((SELECT max(registration_ordinal)+1 FROM amendment_registrations),1) THEN RAISE(ABORT,'amendment order gap')
 WHEN NEW.registration_ordinal=1 AND NOT(NEW.amendment_id='C' AND NEW.amendment_sha256='5b1d8116aa8ed30b407c4804dae191af34a9e4fcc1b9ec292a73b5eeb7c47c83' AND NEW.authorization_mode='INTERACTIVE_OWNER_SIGN') THEN RAISE(ABORT,'exact direct-owner C required first')
 WHEN NEW.registration_ordinal=2 AND NOT(NEW.amendment_id='D' AND NEW.amendment_sha256='c419cbdc0bc26670d5c18b37f183a9cd3481b00680f0b10d3176e482ef1d5be4' AND NEW.authorization_mode='INTERACTIVE_OWNER_SIGN') THEN RAISE(ABORT,'exact direct-owner D required second')
